def naive_retrieval(query):
    # handles simple, single-pass queries
    return f"Naive retrieval handled: {query}"

def multi_hop_retrieval(query):
    # handles complex, multi-part queries
    return f"Multi-hop retrieval handled: {query}"

def fallback_handler(query):
    # catches queries the classifier can't confidently label
    return f"Fallback handler processed: {query}"

def classify_query(query):
    # lightweight classifier: labels the query before real work begins
    words = query.lower().split()
    if len(words) <= 4:
        return "simple"
    if "and" in words or "compare" in words:
        return "complex"
    return "unclear"

def dynamic_router(query):
    label = classify_query(query)
    routes = {
        "simple": naive_retrieval,
        "complex": multi_hop_retrieval,
        "unclear": fallback_handler,
    }
    handler = routes[label]
    return {"label": label, "result": handler(query)}

queries = [
    "Falcon plan cost",
    "Compare the Falcon plan and the Eagle plan pricing",
    "asdkj random text",
]

for q in queries:
    print(f"Query: {q!r}")
    print(dynamic_router(q))
    print()
